const menu=document.querySelector('.menu-toggle');const nav=document.querySelector('#navigation');
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation')}
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';nav.classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();menu.focus()}});nav?.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});
document.addEventListener('click',e=>{if(!e.target.closest('header'))closeMenu()});
document.querySelector('#inquiry')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const d=new FormData(form);const body=`Hello DJ,\n\n${d.get('message')}\n\nName: ${d.get('name')}\nEmail: ${d.get('email')}\nPhone: ${d.get('phone')||'Not provided'}\nInquiry: ${d.get('service')}\n\nSent from the Break Point Investigations website.`;const url=`mailto:DJ@brkpnt.co?subject=${encodeURIComponent('Website inquiry: '+d.get('service'))}&body=${encodeURIComponent(body)}`;const status=document.querySelector('#form-status');status.hidden=false;status.textContent='Your email draft is ready to open. Review it and press Send in your email app. This website has not submitted your inquiry. If no app opens, email DJ@brkpnt.co or call 707.332.0604.';window.location.href=url});
